{"files":[{"content":"/* Cloud Cargo deterministic, DOM-free simulation */
(function () {
  'use strict';
  function rng(seed) { var x = (seed >>> 0) || 1; return function () { x ^= x << 13; x ^= x >>> 17; x ^= x << 5; return (x >>> 0) / 4294967296; }; }
  function shuffle(a, r) { for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(r() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; } return a; }
  function makeBoard(state) {
    var stage = state.stage, count = 4 + stage, bayCount = stage === 0 ? 2 : 3;
    var r = rng((state.seed + 0x9e3779b9 * (stage + 1)) >>> 0), cards = [], groups = [], i;
    for (i = 0; i < bayCount; i++) groups.push([]);
    for (i = 0; i < count; i++) cards.push({ mass: 1 + Math.floor(r() * 5), energy: stage ? Math.floor(r() * 4) : 0, bay: -1 });
    /* A shuffled round-robin hidden manifest guarantees each bay is occupied. */
    var order = shuffle(Array.from({ length: count }, function (_, n) { return n; }), r);
    for (i = 0; i < count; i++) groups[i % bayCount].push(order[i]);
    var bays = groups.map(function (g) {
      var mass = 0, energy = 0;
      g.forEach(function (n) { mass += cards[n].mass; energy += cards[n].energy; });
      return { mass: mass, energy: stage ? energy : null };
    });
    shuffle(cards, r);
    shuffle(bays, r);
    state.cards = cards; state.bays = bays; state.selectedCard = 0; state.focus = 0;
    state.validation = 0; state.dispatching = 0; state.message = 'SELECT A CRATE, THEN A BAY';
  }
  function create(seed) {
    var s = { seed: seed >>> 0, tick: 0, stage: 0, score: 0, assignments: 0, interactions: 0,
      focus: 0, selectedCard: 0, cards: [], bays: [], validation: 0, dispatching: 0,
      terminal: false, message: 'READY TO LOAD', moveLock: 0 };
    makeBoard(s); return s;
  }
  function totals(s, bay) { var m = 0, e = 0; s.cards.forEach(function (c) { if (c.bay === bay) { m += c.mass; e += c.energy; } }); return { mass: m, energy: e }; }
  function exact(s) {
    if (s.cards.some(function (c) { return c.bay < 0; })) return false;
    for (var i = 0; i < s.bays.length; i++) { var t = totals(s, i), b = s.bays[i]; if (t.mass !== b.mass || (b.energy !== null && t.energy !== b.energy)) return false; }
    return true;
  }
  function activate(s, index) {
    var n = s.cards.length;
    if (index < n) { s.selectedCard = index; s.focus = index; s.message = 'CRATE ' + (index + 1) + ' SELECTED'; s.interactions++; return; }
    var bay = index - n;
    if (bay >= 0 && bay < s.bays.length) {
      var c = s.cards[s.selectedCard];
      if (c && c.bay !== bay) { c.bay = bay; s.assignments++; s.interactions++; }
      s.focus = index; s.message = 'ASSIGNED TO BAY ' + String.fromCharCode(65 + bay);
    }
  }
  function pointerTarget(s, p) {
    if (!p) return -1;
    if (p.y >= .08 && p.y <= .39) { var b = Math.floor(p.x * s.bays.length); return b >= 0 && b < s.bays.length ? s.cards.length + b : -1; }
    if (p.y >= .43 && p.y <= .92) { var col = Math.floor(p.x * 3), row = p.y < .675 ? 0 : 1, c = row * 3 + col; return c >= 0 && c < s.cards.length ? c : -1; }
    return -1;
  }
  function step(s, input) {
    input = input || {}; s.tick++; if (s.terminal) return;
    if (s.moveLock > 0) s.moveLock--;
    if (s.dispatching > 0) {
      s.dispatching--;
      if (!s.dispatching) { s.stage++; if (s.stage >= 3) { s.terminal = true; s.message = 'SKYPORT COMPLETE'; } else makeBoard(s); }
      return;
    }
    var target = pointerTarget(s, input.pointer);
    if (target >= 0) activate(s, target);
    else if (input.action) activate(s, s.focus);
    else if (input.x && !s.moveLock) { var max = s.cards.length + s.bays.length - 1; s.focus = (s.focus + (input.x > 0 ? 1 : -1) + max + 1) % (max + 1); s.moveLock = 8; s.interactions++; }
    if (exact(s)) {
      s.validation++;
      s.message = 'MANIFEST VERIFIED — HOLDING LINES';
      if (s.validation >= 30) { s.score += 250 + Math.max(0, 90 - Math.floor(s.tick / 60)) + Math.max(0, 20 - s.assignments); s.dispatching = 42; s.message = 'AIRSHIP DISPATCHED!'; }
    } else { s.validation = 0; }
    if (s.tick >= 3000) { s.terminal = true; s.message = 'CARGO INCOMPLETE'; }
  }
  function observe(s) { return { tick: s.tick, score: s.score, progress: Math.min(100, Math.floor(s.tick * 100 / 3000)), interactions: s.interactions, entities: s.cards.length + s.bays.length + 3 }; }
  function terminal(s) { return !!s.terminal; }
  window.CloudCargoCore = { create: create, step: step, observe: observe, terminal: terminal };
}());
